import (
    "bufio"
    "fmt"
    "math"
    "os"
    "strconv"
    "strings"
)
​
// 计算两个点的切比雪夫距离
func getDistance(coord, tower [3]int) int {
    dx := int(math.Abs(float64(coord[0] - tower[0])))
    dy := int(math.Abs(float64(coord[1] - tower[1])))
    if dx > dy {
        return dx
    }
    return dy
}
​
func getBestCoord(towers [][3]int, radius int) (int, int) {
    xMax, yMax := 0, 0
    for _, tower := range towers {
        if tower[0] > xMax {
            xMax = tower[0]
        }
        if tower[1] > yMax {
            yMax = tower[1]
        }
    }
​
    targetX, targetY := 0, 0
    maxQuality := 0
​
    // 枚举范围内坐标计算最大强度坐标
    for x := 0; x <= xMax; x++ {
        for y := 0; y <= yMax; y++ {
            coord := [3]int{x, y, 0}
            quality := 0
            for _, tower := range towers {
                distance := getDistance(coord, tower)
                if distance <= radius {
                    quality += tower[2] / (1 + distance)
                }
            }
            // 坐标递增，只有超过才更新
            if quality > maxQuality {
                maxQuality = quality
                targetX = x
                targetY = y
            }
        }
    }
​
    return targetX, targetY
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    parts := strings.Fields(line)
    N, _ := strconv.Atoi(parts[0])
    D, _ := strconv.Atoi(parts[1])
​
    towers := make([][3]int, N)
    for i := 0; i < N; i++ {
        line, _ = reader.ReadString('\n')
        parts = strings.Fields(line)
        x, _ := strconv.Atoi(parts[0])
        y, _ := strconv.Atoi(parts[1])
        s, _ := strconv.Atoi(parts[2])
        towers[i] = [3]int{x, y, s}
    }
​
    resX, resY := getBestCoord(towers, D)
    fmt.Println(resX, resY)
}
